const factories = {};
factories["./reconcileJobs"] = function(module, exports, require) {
const {
  DynamoDBClient,
  ScanCommand,
} = require("@aws-sdk/client-dynamodb");

const region = process.env.AWS_REGION || "ap-southeast-1";
const tableName = process.env.JOBS_TABLE || "ddb-cloudtutor-jobs";

const dynamodb = new DynamoDBClient({ region });

const PROCESSING_STATES = new Set([
  "PROCESSING_ASR",
  "PROCESSING_OCR",
  "PROCESSING_VISION",
  "PROCESSING_AI",
]);

function getAgeMinutes(updatedAt, nowMs) {
  const updatedMs = Date.parse(updatedAt);

  if (!Number.isFinite(updatedMs)) {
    return null;
  }

  return Math.floor((nowMs - updatedMs) / 60000);
}

/**
 * Phiên bản kiểm tra: chỉ đọc và báo các job quá hạn.
 * Không thay đổi DynamoDB, không tạo lại AWS job, không gửi SQS.
 */
async function findStaleJobs({
  thresholdMinutes = 30,
  includeTestFixtures = false,
} = {}) {
  if (!Number.isFinite(thresholdMinutes) || thresholdMinutes <= 0) {
    throw new Error("thresholdMinutes phai lon hon 0");
  }

  const nowMs = Date.now();
  const staleJobs = [];
  const missingUpdatedAt = [];
  let lastKey;
  let scannedCount = 0;

  do {
    const response = await dynamodb.send(
      new ScanCommand({
        TableName: tableName,
        ExclusiveStartKey: lastKey,

        ProjectionExpression:
          "job_id, #owner, #status, updated_at, " +
          "processing_version, transcription_job_name, " +
          "ocr_mediaconvert_job_id, vision_mediaconvert_job_id, " +
          "text_handoff_state, vision_handoff_state, test_fixture",

        ExpressionAttributeNames: {
          "#owner": "owner_id",
          "#status": "status",
        },
      })
    );

    scannedCount += response.ScannedCount || 0;

    for (const item of response.Items || []) {
      const status = item.status?.S;

      if (!PROCESSING_STATES.has(status)) {
        continue;
      }

      if (!includeTestFixtures && item.test_fixture?.BOOL === true) {
        continue;
      }

      const ageMinutes = getAgeMinutes(item.updated_at?.S, nowMs);

      const job = {
        job_id: item.job_id?.S || null,
        owner_id: item.owner_id?.S || null,
        status,
        processing_version: item.processing_version?.S || null,
        updated_at: item.updated_at?.S || null,
        age_minutes: ageMinutes,
        transcription_job_name: item.transcription_job_name?.S || null,
        ocr_mediaconvert_job_id:
          item.ocr_mediaconvert_job_id?.S || null,
        vision_mediaconvert_job_id:
          item.vision_mediaconvert_job_id?.S || null,
        text_handoff_state: item.text_handoff_state?.S || null,
        vision_handoff_state: item.vision_handoff_state?.S || null,
      };

      if (ageMinutes === null) {
        missingUpdatedAt.push(job);
      } else if (ageMinutes >= thresholdMinutes) {
        staleJobs.push(job);
      }
    }

    lastKey = response.LastEvaluatedKey;
  } while (lastKey);

  return {
    mode: "READ_ONLY",
    checked_at: new Date(nowMs).toISOString(),
    threshold_minutes: thresholdMinutes,
    include_test_fixtures: includeTestFixtures,
    scanned_count: scannedCount,
    stale_count: staleJobs.length,
    missing_updated_at_count: missingUpdatedAt.length,
    stale_jobs: staleJobs,
    missing_updated_at: missingUpdatedAt,
  };
}

exports.handler = async (event = {}) => {
  const thresholdMinutes =
    event.threshold_minutes === undefined
      ? 30
      : Number(event.threshold_minutes);

  return findStaleJobs({
    thresholdMinutes,
    includeTestFixtures: event.include_test_fixtures === true,
  });
};

if (require.main === module) {
  const thresholdMinutes = Number(process.argv[2] || "30");
  const includeTestFixtures = process.argv.includes("--include-test");

  findStaleJobs({
    thresholdMinutes,
    includeTestFixtures,
  })
    .then((result) => {
      console.log(JSON.stringify(result, null, 2));
    })
    .catch((error) => {
      console.error("Khong kiem tra duoc job:", error.message);
      process.exitCode = 1;
    });
}

module.exports.findStaleJobs = findStaleJobs;
};
factories["./recoverPendingHandoff"] = function(module, exports, require) {
const {
  DynamoDBClient,
  GetItemCommand,
} = require("@aws-sdk/client-dynamodb");

const { dispatchTextHandoff } = require("./dispatchTextHandoff");
const { dispatchVisionHandoff } = require("./dispatchVisionHandoff");

const db = new DynamoDBClient({
  region: process.env.AWS_REGION || "ap-southeast-1",
});

async function read(table, jobId) {
  const response = await db.send(new GetItemCommand({
    TableName: table,
    Key: { job_id: { S: jobId } },
    ConsistentRead: true,
  }));
  return response.Item;
}

/**
 * Phục hồi thủ công checkpoint trên job thử.
 * Mặc định chỉ kiểm tra, không gửi message.
 * Chưa phải bộ reconcile tự động hoặc khóa chống chạy đồng thời.
 */
async function recoverPendingHandoff({ jobId, apply = false }) {
  if (typeof jobId !== "string" || !jobId) {
    throw new Error("Thieu jobId");
  }

  const job = await read(
    process.env.JOBS_TABLE || "ddb-cloudtutor-jobs",
    jobId
  );

  if (!job) throw new Error("Khong tim thay job");

  if (job.test_fixture?.BOOL !== true) {
    throw new Error("Cong cu nay chi cho phep job test_fixture=true");
  }

  const result = await read(
    process.env.RESULTS_TABLE || "ddb-cloudtutor-results",
    jobId
  );

  const ownerId = job.owner_id?.S;
  const version = job.processing_version?.S;
  const source = result?.content_source?.S;
  const key = result?.transcript_key?.S;

  if (
    !ownerId || !version ||
    !["ASR", "OCR", "VISION"].includes(source) ||
    result?.processing_version?.S !== version ||
    !key?.startsWith(`results/${ownerId}/${jobId}/`)
  ) {
    throw new Error("Checkpoint Results khong hop le");
  }

  const state = source === "VISION"
    ? job.vision_handoff_state?.S
    : job.text_handoff_state?.S;

  if (state === "SENT") {
    return { action: "ALREADY_SENT", job_id: jobId };
  }

  if (job.status?.S !== "PROCESSING_AI" || state !== "PENDING") {
    throw new Error("Job khong o PROCESSING_AI/PENDING");
  }

  if (!apply) {
    return {
      action: "WOULD_DISPATCH",
      job_id: jobId,
      source,
      transcript_key: key,
    };
  }

  const expectedQueue = process.env.CT_EXPECTED_AI_TEST_QUEUE_URL;

  if (
    !expectedQueue ||
    process.env.AI_QUEUE_URL !== expectedQueue ||
    !new URL(expectedQueue).pathname
      .split("/").pop().startsWith("sqs-cloudtutor-vision-handoff-test-")
  ) {
    throw new Error("AI_QUEUE_URL khong phai queue handoff test");
  }

  const bucket = process.env.MEDIA_BUCKET;
  if (!bucket) throw new Error("Thieu MEDIA_BUCKET");

  const dispatch = source === "VISION"
    ? dispatchVisionHandoff
    : dispatchTextHandoff;

  await dispatch({
    jobId,
    ownerId,
    processingVersion: version,
    bucket,
    source,
  });

  return { action: "DISPATCHED", job_id: jobId, source };
}

module.exports = { recoverPendingHandoff };

if (require.main === module) {
  recoverPendingHandoff({
    jobId: process.argv[2],
    apply: process.argv.includes("--apply"),
  }).then(result => {
    console.log(JSON.stringify(result, null, 2));
  }).catch(error => {
    console.error(error);
    process.exitCode = 1;
  });
}
};
factories["./dispatchTextHandoff"] = function(module, exports, require) {
const {
  DynamoDBClient,
  GetItemCommand,
  UpdateItemCommand,
} = require("@aws-sdk/client-dynamodb");

const { publishTranscript } = require("./publishTranscript");

const dynamodb = new DynamoDBClient({
  region: process.env.AWS_REGION || "ap-southeast-1",
});

async function readItem(tableName, jobId) {
  const response = await dynamodb.send(
    new GetItemCommand({
      TableName: tableName,
      Key: {
        job_id: { S: jobId },
      },
      ConsistentRead: true,
    })
  );

  return response.Item || null;
}

/**
 * Gửi checkpoint ASR/OCR sang SQS AI.
 *
 * Khi SendMessage thất bại, checkpoint vẫn là PENDING.
 * Nếu đã SENT, hàm không gửi lại trong lần chạy tuần tự.
 */
async function dispatchTextHandoff({
  jobId,
  ownerId,
  processingVersion,
  bucket,
  source,
}) {
  if (
    typeof jobId !== "string" || !jobId ||
    typeof ownerId !== "string" || !ownerId ||
    typeof processingVersion !== "string" || !processingVersion ||
    typeof bucket !== "string" || !bucket
  ) {
    throw new Error("Thieu thong tin ban giao transcript");
  }

  if (!["ASR", "OCR"].includes(source)) {
    throw new Error("Source phai la ASR hoac OCR");
  }

  const jobsTable =
    process.env.JOBS_TABLE || "ddb-cloudtutor-jobs";

  const resultsTable =
    process.env.RESULTS_TABLE || "ddb-cloudtutor-results";

  const job = await readItem(jobsTable, jobId);

  if (!job) {
    throw new Error("Khong tim thay job");
  }

  if (job.owner_id?.S !== ownerId) {
    throw new Error("Owner khong khop");
  }

  if (job.processing_version?.S !== processingVersion) {
    throw new Error("Processing version khong khop");
  }

  const status = job.status?.S;
  const handoffState = job.text_handoff_state?.S;

  if (
    status === "DELETING" ||
    status === "DELETED"
  ) {
    return {
      job_id: jobId,
      skipped: true,
      reason: "JOB_DELETED",
    };
  }

  // Đọc Results để xác nhận checkpoint thực sự thuộc
  // nguồn ASR/OCR mà lượt xử lý này muốn bàn giao.
  const result = await readItem(resultsTable, jobId);

  const transcriptKey = result?.transcript_key?.S;
  const resultSource = result?.content_source?.S;
  const resultVersion = result?.processing_version?.S;

  if (
    !transcriptKey ||
    resultSource !== source ||
    resultVersion !== processingVersion
  ) {
    throw new Error("Results khong khop source hoac version");
  }

  const expectedPrefix = `results/${ownerId}/${jobId}/`;

  if (!transcriptKey.startsWith(expectedPrefix)) {
    throw new Error("Transcript key khong thuoc job");
  }

  if (
    handoffState === "SENT" &&
    [
      "PROCESSING_AI",
      "COMPLETED",
      "COMPLETED_WITH_WARNING",
    ].includes(status)
  ) {
    return {
      job_id: jobId,
      skipped: false,
      handoff_state: "SENT",
      already_sent: true,
    };
  }

  // Chỉ gửi mới khi checkpoint là PENDING và job
  // vẫn đang ở trạng thái PROCESSING_AI.
  if (status !== "PROCESSING_AI" || handoffState !== "PENDING") {
    throw new Error(
      "Job hoac checkpoint khong o trang thai cho phep gui"
    );
  }

  const messageId = await publishTranscript({
    bucket,
    key: transcriptKey,
    jobId,
    ownerId,
    source,
    processingVersion,
  });

  // Nếu AI xử lý nhanh, job có thể đã COMPLETED trước khi
  // Lambda này kịp cập nhật checkpoint.
  await dynamodb.send(
    new UpdateItemCommand({
      TableName: jobsTable,

      Key: {
        job_id: { S: jobId },
      },

      ConditionExpression:
        "#owner = :owner " +
        "AND #status IN (:processing, :completed, :warning) " +
        "AND #version = :version " +
        "AND #handoff = :pending",

      UpdateExpression:
        "SET #handoff = :sent, #updated = :now",

      ExpressionAttributeNames: {
        "#owner": "owner_id",
        "#status": "status",
        "#version": "processing_version",
        "#handoff": "text_handoff_state",
        "#updated": "updated_at",
      },

      ExpressionAttributeValues: {
        ":owner": { S: ownerId },
        ":processing": { S: "PROCESSING_AI" },
        ":completed": { S: "COMPLETED" },
        ":warning": { S: "COMPLETED_WITH_WARNING" },
        ":version": { S: processingVersion },
        ":pending": { S: "PENDING" },
        ":sent": { S: "SENT" },
        ":now": { S: new Date().toISOString() },
      },
    })
  );

  return {
    job_id: jobId,
    skipped: false,
    handoff_state: "SENT",
    already_sent: false,
    message_id: messageId,
    transcript_key: transcriptKey,
    source,
  };
}

module.exports = { dispatchTextHandoff };
};
