  if (job.processing_version?.S !== processingVersion) {
    throw new Error("Processing version khong khop");
  }

  const status = job.status?.S;
  const handoffState = job.vision_handoff_state?.S;

  // Nếu checkpoint đã SENT, cho phép nhận diện lại khi job
  // đang xử lý AI hoặc đã hoàn tất.
  if (
    handoffState === "SENT" &&
    [
      "PROCESSING_AI",
      "COMPLETED",
      "COMPLETED_WITH_WARNING",
    ].includes(status)
  ) {
    return {
      job_id: jobId,
      handoff_state: "SENT",
      already_sent: true,
    };
  }

  // Chỉ bắt đầu gửi một checkpoint PENDING khi job
  // vẫn đang ở trạng thái PROCESSING_AI.
  if (status !== "PROCESSING_AI") {
    throw new Error("Trang thai job khong cho phep gui Vision");
  }

  if (job.vision_handoff_state?.S !== "PENDING") {
    throw new Error("Checkpoint Vision khong o trang thai PENDING");
  }

  const result = await readItem(resultsTable, jobId);

  const transcriptKey = result?.transcript_key?.S;
  const source = result?.content_source?.S;
  const resultVersion = result?.processing_version?.S;

  if (
    !transcriptKey ||
    source !== "VISION" ||
    resultVersion !== processingVersion
  ) {
    throw new Error("Results Vision khong hop le");
  }

  const expectedPrefix = `results/${ownerId}/${jobId}/`;

  if (!transcriptKey.startsWith(expectedPrefix)) {
    throw new Error("Transcript key khong thuoc job");
  }

  // Gửi trước. Nếu gửi thất bại, checkpoint vẫn là PENDING.
  const messageId = await publishTranscript({
    bucket,
    key: transcriptKey,
    jobId,
    ownerId,
    source: "VISION",
    processingVersion,
  });

  // Chỉ đánh dấu SENT nếu job vẫn ở đúng trạng thái và version.
  await dynamodb.send(
    new UpdateItemCommand({
      TableName: jobsTable,

      Key: {
        job_id: { S: jobId },
      },

      ConditionExpression:
        "#owner = :owner " +
        "AND #status IN (:status, :completed, :completedWarning) " +
        "AND #version = :version AND #handoff = :pending",

      UpdateExpression:
        "SET #handoff = :sent, #updated = :now",

      ExpressionAttributeNames: {
        "#owner": "owner_id",
        "#status": "status",
        "#version": "processing_version",
        "#handoff": "vision_handoff_state",
        "#updated": "updated_at",
      },

      ExpressionAttributeValues: {
        ":owner": { S: ownerId },
        ":status": { S: "PROCESSING_AI" },
        ":completed": { S: "COMPLETED" },
        ":completedWarning": { S: "COMPLETED_WITH_WARNING" },
        ":version": { S: processingVersion },
        ":pending": { S: "PENDING" },
        ":sent": { S: "SENT" },
        ":now": { S: new Date().toISOString() },
      },
    })
  );

  return {
    job_id: jobId,
    handoff_state: "SENT",
    already_sent: false,
    message_id: messageId,
    transcript_key: transcriptKey,
  };
}

module.exports = { dispatchVisionHandoff };
};
factories["./publishTranscript"] = function(module, exports, require) {
const {
  SQSClient,
  SendMessageCommand,
} = require("@aws-sdk/client-sqs");

const sqsClient = new SQSClient({
  region: process.env.AWS_REGION || "ap-southeast-1",
});

async function publishTranscript({
  bucket,
  key,
  jobId,
  ownerId,
  source,
  processingVersion = "1",
}) {
  const queueUrl = process.env.AI_QUEUE_URL;

  if (!queueUrl) {
    throw new Error("Thieu AI_QUEUE_URL");
  }

  if (!bucket || !key || !jobId || !ownerId) {
    throw new Error("Thieu thong tin ban giao AI");
  }

  if (!["ASR", "OCR", "VISION"].includes(source)) {
    throw new Error(`Nguon noi dung khong hop le: ${source}`);
  }

  const message = {
    schema_version: "1.0",
    job_id: jobId,
    owner_id: ownerId,
    bucket,
    transcript_key: key,
    source,
    processing_version: String(processingVersion),
    handoff_id: `${ownerId}/${jobId}/v${processingVersion}`,
  };

  const result = await sqsClient.send(
    new SendMessageCommand({
      QueueUrl: queueUrl,
      MessageBody: JSON.stringify(message),
    })
  );

  console.log("Da gui cong viec AI:", {
    job_id: jobId,
    handoff_id: message.handoff_id,
    message_id: result.MessageId,
    transcript_key: key,
  });

  return result.MessageId;
}

module.exports = { publishTranscript };
};
factories["./scheduledPendingRecovery"] = function(module, exports, require) {
const { randomUUID } = require("node:crypto");
const {
  DynamoDBClient, GetItemCommand, UpdateItemCommand,
} = require("@aws-sdk/client-dynamodb");
const { findStaleJobs } = require("./reconcileJobs");
const { recoverPendingHandoff } = require("./recoverPendingHandoff");

const db = new DynamoDBClient({
  region: process.env.AWS_REGION || "ap-southeast-1",
});
const table = process.env.JOBS_TABLE || "ddb-cloudtutor-jobs";

exports.handler = async (event = {}, context) => {
  const thresholdMinutes = Number(event.threshold_minutes ?? 30);

  // Báo cáo job thật vẫn chỉ đọc.
  const report = await findStaleJobs({
    thresholdMinutes,
    includeTestFixtures: false,
  });

  console.log(JSON.stringify({
    event: "RECONCILE_SUMMARY",
    stale_count: report.stale_count,
    missing_updated_at_count: report.missing_updated_at_count,
  }));

  for (const job of report.stale_jobs) {
    console.warn(JSON.stringify({ event: "STALE_JOB", ...job }));
  }

  for (const job of report.missing_updated_at) {
    console.warn(JSON.stringify({
      event: "JOB_MISSING_UPDATED_AT", ...job,
    }));
  }

  report.recovery = [];

  if (process.env.AUTO_RECOVER_TEST_PENDING !== "true") {
    return report;
  }

  // ID chỉ định phục vụ kiểm thử; vẫn phải vượt kiểm tra fixture.
  const candidates = event.recovery_test_job_id
    ? [{ job_id: event.recovery_test_job_id }]
    : (await findStaleJobs({
        thresholdMinutes,
        includeTestFixtures: true,
      })).stale_jobs.filter(job =>
        job.status === "PROCESSING_AI" &&
        (
          job.text_handoff_state === "PENDING" ||
          job.vision_handoff_state === "PENDING"
        )
      );

  let failures = 0;

  for (const candidate of candidates.slice(0, 3)) {
    if (context && context.getRemainingTimeInMillis() < 25000) break;

    const key = { job_id: { S: candidate.job_id } };
    const read = await db.send(new GetItemCommand({
      TableName: table,
      Key: key,
      ConsistentRead: true,
    }));

    const job = read.Item;

    // Không sửa hoặc gửi message cho job thật.
    if (
      job?.test_fixture?.BOOL !== true ||
      job.status?.S !== "PROCESSING_AI" ||
      !job.owner_id?.S ||
      !job.processing_version?.S
    ) {
      report.recovery.push({
        job_id: candidate.job_id,
        action: "SKIPPED_NOT_ELIGIBLE",
      });
      continue;
    }

    const field = job.vision_handoff_state?.S === "PENDING"
      ? "vision_handoff_state"
      : job.text_handoff_state?.S === "PENDING"
        ? "text_handoff_state"
        : null;

    if (!field) {
      report.recovery.push({
        job_id: candidate.job_id,
        action: "SKIPPED_NOT_PENDING",
      });
      continue;
    }

    const token = randomUUID();
    const now = Math.floor(Date.now() / 1000);

    try {
      // Khóa giữa các lượt reconcile; không phải khóa mọi worker.
      await db.send(new UpdateItemCommand({
        TableName: table,
        Key: key,
        ConditionExpression:
          "#fixture = :yes AND #status = :ai " +
          "AND #owner = :owner AND #version = :version " +
          "AND #handoff = :pending " +
          "AND (attribute_not_exists(#lease) OR #lease < :now) " +
          "AND (attribute_not_exists(#next) OR #next <= :now) " +
          "AND (attribute_not_exists(#attempts) OR #attempts < :max)",
        UpdateExpression:
          "SET #lease = :expiry, #token = :token, #next = :next " +
          "ADD #attempts :one",
        ExpressionAttributeNames: {
          "#fixture": "test_fixture",
          "#status": "status",
          "#owner": "owner_id",
          "#version": "processing_version",
          "#handoff": field,
          "#lease": "pending_recovery_lease_until",
          "#token": "pending_recovery_token",
          "#next": "pending_recovery_next_at",
          "#attempts": "pending_recovery_attempts",
        },
        ExpressionAttributeValues: {
          ":yes": { BOOL: true },
